.dmm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dmm-root,.dmm-root *,.dmm-root *::before,.dmm-root *::after{box-sizing:border-box}
.dmm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dmm-root img{display:block;border:0;max-width:none}
.dmm-root > [data-node-id]{will-change:transform}
.dmm-root [hidden]{display:none!important}
.dmm-root [data-sh-theme="light"]{display:none!important}
.dmm-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.dmm-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.dmm-root .n2921_1201{align-content:stretch;display:flex;gap:35px;align-items:center;padding-left:5px;position:relative;flex-shrink:0;width:100%;height:22px}
.dmm-root .nI2921_1201_464_89{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;line-height:0;place-items:start;position:relative;flex-shrink:0}
.dmm-root .nI2921_1201_464_90{grid-column:1;height:3.559px;margin-left:0;margin-top:9px;position:relative;grid-row:1;width:3.561px}
.dmm-root .x27{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dmm-root .nI2921_1201_464_91{word-break:break-word;grid-column:1;display:flex;flex-direction:column;font-family:"NanumGothic","Pretendard",sans-serif;font-weight:700;height:22px;justify-content:center;margin-left:19px;margin-top:0;font-style:normal;overflow:hidden;position:relative;grid-row:1;font-size:20px;text-overflow:ellipsis;color:var(--wa-text, #fff);width:150px;white-space:nowrap}
.dmm-root .x28{line-height:normal;overflow:hidden;text-overflow:ellipsis}
.dmm-root .nI2921_1201_464_92{position:relative;flex-shrink:0;width:9.962px;height:9.962px}
.dmm-root .x29{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dmm-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.dmm-root[data-theme="light"] [data-name="Badge/Critical"] p,.dmm-root[data-theme="light"] [data-name^="status-critical"] p,.dmm-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.dmm-root[data-theme="light"] [data-name="Badge/Major"] p,.dmm-root[data-theme="light"] [data-name^="status-major"] p,.dmm-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.dmm-root[data-theme="light"] [data-name="Badge/Minor"] p,.dmm-root[data-theme="light"] [data-name^="status-minor"] p,.dmm-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.dmm-root[data-theme="light"] [data-name="Badge/Warning"] p,.dmm-root[data-theme="light"] [data-name^="status-warning"] p,.dmm-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.dmm-root[data-theme="light"] [data-name="Badge/Normal"] p,.dmm-root[data-theme="light"] [data-name^="status-normal"] p,.dmm-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.dmm-root[data-theme="light"] [data-name="Button/Ack"] p,.dmm-root[data-theme="light"] [data-name="Button/Ack All"] p,.dmm-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.dmm-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.dmm-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.dmm-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.dmm-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.dmm-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.dmm-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.dmm-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.dmm-root[data-theme="light"] [data-name="Symbol"] > [data-name="Shape"] img{opacity:.32;filter:saturate(.7)}
.dmm-root[data-theme="light"] :is([data-name="Floor Layer"],[data-name="Floor"] > [data-name="Part"]) > *{opacity:.18}
.dmm-root[data-theme="light"] [data-name="Floor"] img{opacity:.25}
.dmm-root[data-theme="light"] [data-name="Effect"] > * > *,.dmm-root[data-theme="light"] [data-name="Effect"] img{opacity:.45}
.dmm-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.dmm-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.dmm-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1668d4)!important}
.dmm-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.dmm-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.dmm-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.dmm-root[data-theme="light"] .nI2921_1201_464_91{color:var(--wa-point, #0f2238)}
.dmm-root[data-theme="light"] [data-name="Header"] [data-name="Nav"]{background:transparent!important}
.dmm-root[data-theme="light"] [data-name="Header"]:has([data-name="Icon Logout"]) p[data-name="Value"]{background-image:linear-gradient(180deg,var(--wa-point, #1d4fc4) 40%,var(--wa-point, #0a8fd0))!important}
.dmm-root[data-theme="light"] :is([data-name="Button/Drawing Info"],[data-name="Button/Scenario"],[data-name="Button/Equipment Info"]) > [data-name="Background"]{background-image:linear-gradient(-39.768deg,var(--wa-bg, #ffffff) 50.648%,var(--wa-bg, #e6ecf4) 50.648%)!important;box-shadow:inset 0 0 0 1px #c3d0e0}
.dmm-root[data-theme="light"] [data-name="Button/Close All"] > [data-name="Background"]{background-image:linear-gradient(-24.4deg,var(--wa-point, #e3e9f1) 54.2%,var(--wa-bg, #f4f7fb) 54.2%)!important;box-shadow:inset 0 0 0 1px #b8c6d8}
.dmm-root[data-theme="light"] [data-name="Button/Close All"] p{color:var(--wa-point, #24374e)!important}
.dmm-root[data-theme="light"] [data-name="Event Log"] [data-name="Row"] > [data-name="Label"] p{color:var(--wa-text, #fff)!important}
.dmm-root[data-theme="light"] [data-name="Button Group"] [data-name="Button/Reset"] p{color:var(--wa-point, #24374e)!important}
.dmm-root[data-theme="light"] [data-name="Title Bar"]::after{left:-1px!important;right:-1px!important}
